// same guards the scan applies (mutexAmong scope; 'blocked' exempts).
function mutexHoldersOf(items, q) {
    var among = (q.mutexAmong && q.mutexAmong.length) ? q.mutexAmong : null;
    return items.filter(function (p) {
        var labels = p.labels || [];
