        mutexSelfHeals: num(s.mutexSelfHeals) + 1,
        phantomHolderTicks: num(s.phantomHolderTicks) + 1,
        consecutivePhantomTicks: num(s.consecutivePhantomTicks) + 1,
        alarms: alarms
