    console.warn('  ⚠️  ' + key + ' ghost-cancel flap: machine re-dispatch ' +
        flaps + '× and the head still reads ghost-cancel (merge gate still waiting) — ' +
        'a guest PR cannot self-escape (gh-1000 E3)');
