function hasRecentHeadRun(runs, graceMs) {
    var now = Date.now();
    return (runs || []).some(function (r) {
        if (!r) return false;
        if (r.status === 'queued' || r.status === 'in_progress' ||
            r.status === 'waiting' || r.status === 'pending' ||
            r.status === 'requested') return true;
        if (r.status === 'completed') {
