        assert.ok(body.indexOf('kicker / sm-liveness') !== -1 && body.indexOf('docs-freshness') !== -1,
            'names every rerun context');
        assert.ok(body.indexOf('gh-755') !== -1, 'cites the gh-755 evidence (not the #682 wave)');
