                return;
            }
            if (DRY) {
                console.log('  🧪 [dry] zombie-swept check-run ' + z.id + ' ("' +
                            (z.name || '?') + '") completed/neutral on ' +
                            String(headSha).slice(0, 7) + ' (gh-998)');
                out.concluded++;
                return;
            }
