function gh857GreenRule() {
    return { source: 'github',
        query: { type: 'pr', labels: ['pr_approved', 'ai_validating'],
                 notMergeState: ['BEHIND', 'DIRTY', 'CLEAN'], checks: ['green'], draft: false },
