function recordPhantomHeal(state, label, cachedHolders, liveHolders, atIso) {
    var s = state || defaultState();
    var alarmLabel = str(label) || DEFAULT_MUTEX_LABEL;
    var sig = uniquePositive(cachedHolders).join(',');
