Refactor phantomAlarmOf to reduce CC — extract the label/repo/at resolution into tiny helpers with ternaries? Logical operators still count. Use helper functions:

```js
function snapshotLabelOf(liveSnapshot, cachedSnapshot) {
   if (liveSnapshot && liveSnapshot.label) return liveSnapshot.label;
   if (cachedSnapshot && cachedSnapshot.label) return cachedSnapshot.label;
   return DEFAULT_MUTEX_LABEL;
}
function snapshotRepoOf(liveSnapshot, cachedSnapshot) {
   if (liveSnapshot && liveSnapshot.repo) return liveSnapshot.repo;
   return cachedSnapshot && cachedSnapshot.repo;
}
function phantomAlarmOf(liveSnapshot, cachedSnapshot, cached, live) {
